// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    Recorder r;

    function setUp() public { c = new demo(); r = new Recorder(); }

    // fuzzed params: from address, number of tos (as uint8 to keep array size reasonable), value
    function testFuzz_property(address from, uint8 nTos, uint256 v) public {
        // keep nTos in 1..5 to make the helper record a small number of calls but at least 1
        uint256 len = bound(nTos, 1, 5);

        // build tos array with distinct addresses derived from `from` and index so fuzzer explores calldata
        address[] memory tos = new address[](len);
        for (uint i = 0; i < len; i++) {
            // create addresses from keccak to avoid being all EOAs with zero code (recorder is used as callee anyway)
            tos[i] = address(uint160(uint256(keccak256(abi.encodePacked(from, i, v)))));
        }

        // Call through c.transfer with our recorder as the caddress so we can observe what selector and args were received
        // The correct contract always encodes selector for transferFrom(address,address,uint256)
        // The mutant encodes approve(address,uint256) instead, which will result in different recorded selector/decoding

        // wrap call to observe it does not revert (both versions return true and don't revert here)
        bool ok;
        try c.transfer(from, address(r), tos, v) {
            ok = true;
        } catch {
            ok = false;
        }

        // The recorder captured each call's raw selector and decoded args when possible.
        // We assert the general rule: for every recorded call i, the selector equals the transferFrom selector
        // and the decoded args match (from, tos[i], v). The mutant will cause the selector to differ for some inputs,
        // making this assertion fail for those cases.

        bytes4 expectedId = bytes4(keccak256("transferFrom(address,address,uint256)"));

        // must have succeeded
        assertTrue(ok);

        // check recorder observed exactly len calls
        assertTrue(r.callCount() == len);

        for (uint i = 0; i < len; i++) {
            // each recorded selector must match expected transferFrom selector
            assertTrue(r.selectors(i) == expectedId);
            // and decoded args must match
            (address a0, address a1, uint256 a2) = r.decodedTransferFromArgs(i);
            assertTrue(a0 == from);
            assertTrue(a1 == tos[i]);
            assertTrue(a2 == v);
        }
    }
}

// Recorder that implements the transferFrom signature so that calls with that selector are ABI-decoded
contract Recorder {
    // recordings
    bytes4[] public _selectors;
    bytes[] public _calldatas;

    // decoded records for transferFrom selector calls
    address[] public arg0s;
    address[] public arg1s;
    uint256[] public arg2s;

    // generic fallback to record selector and calldata when function signature doesn't match
    fallback() external payable {
        bytes4 sel;
        assembly { sel := calldataload(0) }
        _selectors.push(sel);
        bytes memory d = msg.data;
        _calldatas.push(d);

        // attempt to decode as transferFrom(address,address,uint256)
        if (msg.data.length == 4 + 32*3) {
            // decode args from calldata offset 4
            bytes memory payload = msg.data[4:];
            (address a0, address a1, uint256 a2) = abi.decode(payload, (address, address, uint256));
            arg0s.push(a0);
            arg1s.push(a1);
            arg2s.push(a2);
        } else {
            // push placeholders so indices align
            arg0s.push(address(0));
            arg1s.push(address(0));
            arg2s.push(0);
        }
    }

    // helper getters for test to read records
    function callCount() external view returns (uint) { return _selectors.length; }
    function selectors(uint i) external view returns (bytes4) { return _selectors[i]; }
    function decodedTransferFromArgs(uint i) external view returns (address, address, uint256) {
        return (arg0s[i], arg1s[i], arg2s[i]);
    }
}
